import { cx } from '@/lib/cx';
import { Plate } from './plate';
import type { PlateProps } from './plate';
import './split.css';

/**
 * B46 · Split — the band-less page, cut in half, with the card ACROSS THE
 * CUT. Two flat surfaces meet on one seam — ink and wall, side by side or
 * stacked — and the Plate sits centred on that seam, so half the card is on
 * ink and half is on wall.
 *
 * This is B2's overlap, finished. The Sheet spends it once per page by
 * pulling its first row 44px over the band edge; a Plate has no Sheet and no
 * band, so the same physics arrive as a page type: not a card that peeks
 * over an edge, a card that STRADDLES one. It is the only 76° layout where
 * paper crosses a surface boundary rather than resting on one.
 *
 * The halves are BACKGROUND and nothing else. No statement, no widget, no
 * screenshot, no illustration: they carry no text, so they are marked
 * aria-hidden and the page reads as exactly the Plate it is. A1 refuses
 * gradients, so the cut is two real elements rather than a colour stop —
 * which is also why it lands on a hard pixel instead of a soft blend.
 *
 * B24 is composed verbatim, with one consequence: everything the Plate puts
 * on the WALL moves INTO the card. Centred above and below a card that
 * straddles the seam, the wordmark and the footer would each land half on
 * ink and half on paper — ink type on ink, which reads as a rendering fault.
 * Both become rows of the card, hairline-ruled, and the Plate's own slots
 * are emptied. Nothing else about the Plate changes: same anatomy, same one
 * h1, same one primary, same 400px measure.
 *
 * One job: carry a single decision on the line between two surfaces.
 */
export interface SplitProps extends PlateProps {
  /**
   * `side` (default) cuts the page left/right: ink, then wall, with the card
   * on the vertical seam. `stacked` cuts it top/bottom, card on the
   * horizontal seam. Below 1000px `side` becomes `stacked` on its own — a
   * vertical seam behind a full-width card is a seam nobody can see.
   */
  orientation?: 'side' | 'stacked';
}

/* The mark, inside the card. It keeps the Plate's own recipe — six in seed,
   degree in faint ink — and takes a hairline under it so it reads as the
   card's first row rather than a badge floating over the title. Left, not
   centred: every other line in a 76° card starts on the same edge. */
const CARD_MARK = (
  <div className="sv-split__mark">
    <span className="sv-plate__wordmark" role="img" aria-label="Seventy Six Degrees">
      <span aria-hidden="true">7</span>
      <span className="sv-plate__wordmark-six" aria-hidden="true">6</span>
      <span className="sv-plate__wordmark-deg" aria-hidden="true">°</span>
    </span>
  </div>
);

export function Split({ orientation = 'side', footer, className, children, ...plate }: SplitProps) {
  return (
    <div className={cx('sv-split', `sv-split--${orientation}`, className)}>
      {/* Decoration, stated as such: two empty surfaces meeting on a seam.
          There is no skip link, because B24's exception holds — a Split has
          nothing to skip past to reach the decision. */}
      <div className="sv-split__halves" aria-hidden="true">
        <div className="sv-split__ink" />
        <div className="sv-split__wall" />
      </div>
      {/* wordmark and footer are intercepted, not passed: on a Split they are
          rows of the card, and the Plate's wall-side slots stay empty. */}
      <Plate {...plate} wordmark={null} className="sv-split__plate">
        {CARD_MARK}
        {children}
        {footer && <p className="sv-split__foot">{footer}</p>}
      </Plate>
    </div>
  );
}

/* B46 · Split — two surfaces, one seam, and the card across it. */

@layer sv-components {
  /* The halves and the Plate share ONE grid cell, so the card floats over
     the seam without absolute positioning and without a z-index: they are
     both ordinary grid items, and the later one in the DOM paints on top. */
  .sv-split {
    display: grid;
    min-height: 100vh;
    min-height: 100dvh;
  }

  .sv-split__halves,
  .sv-split__plate {
    grid-area: 1 / 1;
  }

  /* Two real elements, not a colour stop: A1 bans gradients, and a hard cut
     is the point — the seam has to be a line the card can straddle. */
  .sv-split__halves {
    display: grid;
  }

  .sv-split__ink {
    background: var(--sv-band);
  }

  .sv-split__wall {
    background: var(--sv-wall);
  }

  /* minmax(0, 1fr) even though these halves are EMPTY by specification and a
     bare 1fr would behave identically — rule 19 is written to be unarguable,
     and an exemption granted once is an exemption someone copies onto a track
     that does hold content. The cheaper move is to satisfy the rule. */
  .sv-split--side .sv-split__halves {
    grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
  }

  .sv-split--stacked .sv-split__halves {
    grid-template-rows: 1fr 1fr;
  }

  /* Centred on the seam in BOTH axes, and TRANSPARENT: the Plate paints
     --sv-wall on its own, which over two halves would read as a pale box
     bleeding across the seam. Here the halves are the surface and only the
     card is paper. */
  .sv-split__plate {
    /* STRETCHED horizontally, centred vertically — and the difference is the
       whole bug it fixes. `place-self: center` shrink-wraps the plate to its
       widest LINE, so the same 400px card came out 400px on Create account
       (whose password hint runs two lines) and 286px on Sign in (whose longest
       line is a button label). A card's measure is a constant of the system,
       never a function of the copy inside it — two auth screens side by side
       have to be the same object.
       Stretching is safe because the plate paints nothing: the halves are the
       surface, `background: none` is set below, and the Plate's own
       `justify-items: center` puts its 400px inner exactly on the seam. */
    align-self: center;
    justify-self: stretch;
    min-height: 0;
    background: none;
  }

  /* The Plate's wall-side mark slot is emptied by wordmark={null}, so the
     row it would have occupied goes with it. */
  .sv-split__plate .sv-plate__mark {
    display: none;
  }

  /* ---- The mark and the footer, now the card's first and last rows ---- */

  /* CENTRED, and it is the one line in the card that is. Everything else —
     the title, the fields, the footer — is left-aligned, because that is how
     the system sets type. The wordmark is not type in that sense: it is the
     mark the page belongs to, it is the same object on all seven auth
     screens, and centred is where a reader looks for it. B24 already centres
     it on a plain Plate, above the card; when B46 moves it INTO the card it
     keeps the position it had. */
  .sv-split__mark {
    padding-bottom: var(--sv-s4);
    margin-bottom: var(--sv-s5);
    border-bottom: 1px solid var(--sv-line);
    text-align: center;
  }

  /* Mono voice, sentence case, left like every other line in the card —
     this line carries legal text, support links and error ids, which
     uppercase tracking makes unreadable. */
  .sv-split__foot {
    padding-top: var(--sv-s4);
    margin-top: var(--sv-s5);
    border-top: 1px solid var(--sv-line);
    font-family: var(--sv-font-mono);
    font-size: 11px;
    line-height: 1.6;
    color: var(--sv-ink-soft);
  }

  .sv-split__foot a {
    color: var(--sv-seed-text);
  }

  /* ---- The floor ---- */

  /* A vertical seam behind a card that has grown to the full width is a seam
     nobody can see, so side turns into stacked and keeps the signature. The
     card is still centred, so it still straddles (C7 — nothing is lost). */
  @media (max-width: 1000px) {
    .sv-split--side .sv-split__halves {
      grid-template-columns: none;
      grid-template-rows: 1fr 1fr;
    }
  }
}
